<?php
require __DIR__.'/_common.php'; admin_require(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($action==='delete'){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([$id]);flash('Pack supprimé');redirect_self();}if($action==='toggle'){$pdo->prepare('UPDATE products SET active=1-active WHERE id=?')->execute([$id]);flash('Statut du pack modifié');redirect_self();}$data=[(int)$_POST['game_id'],trim((string)$_POST['name']),trim((string)$_POST['slug']),trim((string)$_POST['provider_sku']),trim((string)$_POST['maketou_cart_id']),trim((string)$_POST['image_url']),max(0,(float)$_POST['price']),trim((string)$_POST['currency']),trim((string)$_POST['delivery_type']),isset($_POST['active'])?1:0];if($id){$q=$pdo->prepare('UPDATE products SET game_id=?,name=?,slug=?,provider_sku=?,maketou_cart_id=?,image_url=?,price=?,currency=?,delivery_type=?,active=? WHERE id=?');$q->execute([...$data,$id]);}else{$q=$pdo->prepare('INSERT INTO products(game_id,name,slug,provider_sku,maketou_cart_id,image_url,price,currency,delivery_type,active) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute($data);}flash('Pack enregistré');redirect_self();}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$games=$pdo->query('SELECT * FROM games ORDER BY name')->fetchAll();$products=$pdo->query('SELECT p.*,g.name game FROM products p JOIN games g ON g.id=p.game_id ORDER BY g.name,p.price')->fetchAll();admin_layout_start('Packs');echo '<form method="post" class="form"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($edit['id']??0).'"><select name="game_id" required>';foreach($games as $g)echo '<option value="'.h($g['id']).'" '.((int)($edit['game_id']??0)===(int)$g['id']?'selected':'').'>'.h($g['name']).'</option>';echo '</select><input name="name" placeholder="Nom du pack" value="'.h($edit['name']??'').'" required><input name="slug" placeholder="slug" value="'.h($edit['slug']??'').'" required><input name="price" type="number" step="0.01" placeholder="Prix XAF" value="'.h($edit['price']??'').'" required><input name="currency" value="'.h($edit['currency']??'XAF').'" maxlength="3"><input name="provider_sku" placeholder="SKU Topup.dev" value="'.h($edit['provider_sku']??'').'"><input name="maketou_cart_id" placeholder="Lien/ID panier Maketou" value="'.h($edit['maketou_cart_id']??'').'" required><input name="image_url" placeholder="URL image" value="'.h($edit['image_url']??'').'"><input name="delivery_type" value="'.h($edit['delivery_type']??'game_id').'" placeholder="Type de données client"><label><input type="checkbox" name="active" '.(!isset($edit)||!empty($edit['active'])?'checked':'').'> Actif</label><button>Enregistrer</button></form><table><tr><th>Jeu</th><th>Pack</th><th>Prix</th><th>SKU</th><th>Maketou</th><th>Actif</th><th>Actions</th></tr>';foreach($products as $p)echo '<tr><td>'.h($p['game']).'</td><td>'.h($p['name']).'</td><td>'.h($p['price'].' '.$p['currency']).'</td><td>'.h($p['provider_sku']).'</td><td>'.h($p['maketou_cart_id']).'</td><td>'.(!empty($p['active'])?'Oui':'Non').'</td><td><a href="?edit='.h($p['id']).'">Modifier</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($p['id']).'"><input type="hidden" name="action" value="toggle"><button>Activer/Désactiver</button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><input type="hidden" name="id" value="'.h($p['id']).'"><input type="hidden" name="action" value="delete"><button onclick="return confirm(\'Supprimer ?\')">Supprimer</button></form></td></tr>';echo '</table>';admin_layout_end();